long long count_subarrays_divisible_by_k(std::vector<int> nums, int k) {
    // correct but slow: it checks every subarray
    long long count = 0;
    for (size_t i = 0; i < nums.size(); ++i) {
        long long total = 0;
        for (size_t j = i; j < nums.size(); ++j) {
            total += nums[j];
            if (total % k == 0) ++count;
        }
    }
    return count;
}

