#include <vector>
#include <unordered_map>
long long count_subarrays_divisible_by_k(std::vector<int> nums, int k) {
    std::unordered_map<int, long long> seen;
    seen[0] = 1;
    long long total = 0, count = 0;
    for (int x : nums) {
        total = ((total + x) % k + k) % k;
        count += seen[(int)total];
        ++seen[(int)total];
    }
    return count;
}

